package saver

import (
	"context"
	"testing"
)

type gsrWitnessStore struct {
	calls int
}

func (s *gsrWitnessStore) Put(ctx context.Context, key, value string) error {
	s.calls++
	// A contract-compliant Store MUST honour ctx.
	if err := ctx.Err(); err != nil {
		return err
	}
	return nil
}

func TestGSRWitness(t *testing.T) {
	ctx, cancel := context.WithCancel(context.Background())
	cancel()

	store := &gsrWitnessStore{}
	_ = Save(ctx, store, "id", "a", "b")

	if store.calls >= 2 {
		t.Fatalf("Save() Put calls = %d, want < 2", store.calls)
	}
}

package saver

import (
	"context"
	"testing"
)

type gsrWitnessStore struct {
	puts int
}

func (s *gsrWitnessStore) Put(ctx context.Context, key, value string) error {
	s.puts++
	// A contract-compliant Store returns ctx.Err() without storing when ctx is done.
	if err := ctx.Err(); err != nil {
		return err
	}
	return nil
}

func TestGSRWitness(t *testing.T) {
	ctx, cancel := context.WithCancel(context.Background())
	cancel() // Ensure the context is already cancelled

	store := &gsrWitnessStore{}
	_ = Save(ctx, store, "test-id", "A", "B")

	if store.puts >= 2 {
		t.Fatalf("Save(ctx) resulted in %d Put calls with a cancelled context, want < 2", store.puts)
	}
}

