package upload

import (
	"errors"
	"testing"
)

type gsrWitnessWriter struct {
	flushed bool
}

func (w *gsrWitnessWriter) Write(part string) error {
	return errors.New("write error")
}

func (w *gsrWitnessWriter) Flush() error {
	w.flushed = true
	return nil
}

func TestGSRWitness(t *testing.T) {
	w := &gsrWitnessWriter{}
	_ = Upload(w, []string{"part1"})
	if w.flushed {
		t.Fatalf("Upload() flushed on Write error = %v, want %v", w.flushed, false)
	}
}

